//! Embedded void-and-cluster blue-noise rank texture (`ED-on-GPU.md` §3.2.1).
//!
//! Generated by `tools/void_and_cluster/generate.py` (Ulichney 1993).
//! Canonical bytes: `assets/blue_noise_128_u16.raw` (little-endian u16).

use std::sync::OnceLock;

/// 128×128 u16 rank texture (permutation of `0..16383`).
pub struct BlueNoiseTexture {
    ranks: &'static [u16],
}

impl BlueNoiseTexture {
    pub const SIZE: u32 = 128;
    pub const PIXEL_COUNT: usize = (Self::SIZE * Self::SIZE) as usize;

    /// Load the committed little-endian rank table embedded at compile time.
    pub fn embedded() -> Self {
        Self {
            ranks: ranks_slice(),
        }
    }

    #[inline]
    pub fn as_slice(&self) -> &'static [u16] {
        self.ranks
    }

    #[inline]
    pub fn rank(&self, x: u32, y: u32) -> u16 {
        let size = Self::SIZE;
        let idx = ((y % size) * size + (x % size)) as usize;
        self.ranks[idx]
    }
}

fn ranks_slice() -> &'static [u16] {
    static RANKS: OnceLock<[u16; BlueNoiseTexture::PIXEL_COUNT]> = OnceLock::new();
    RANKS
        .get_or_init(|| {
            let bytes: &[u8] = include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/../../assets/blue_noise_128_u16.raw"
            ));
            assert_eq!(
                bytes.len(),
                BlueNoiseTexture::PIXEL_COUNT * 2,
                "blue_noise_128_u16.raw size mismatch"
            );
            let mut ranks = [0u16; BlueNoiseTexture::PIXEL_COUNT];
            for (i, chunk) in bytes.as_chunks::<2>().0.iter().enumerate() {
                ranks[i] = u16::from_le_bytes([chunk[0], chunk[1]]);
            }
            ranks
        })
        .as_slice()
}

/// Debug-only integrity check against the committed sha256 of the raw table.
#[cfg(debug_assertions)]
pub fn verify_texture_hash() {
    use sha2::{Digest, Sha256};
    let bytes = include_bytes!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../assets/blue_noise_128_u16.raw"
    ));
    let actual = format!("{:x}", Sha256::digest(bytes));
    let expected = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../assets/blue_noise_128_u16.raw.sha256"
    ))
    .split_whitespace()
    .next()
    .expect("raw.sha256 must contain a digest");
    assert_eq!(actual, expected, "blue noise texture hash mismatch");
}

#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest, Sha256};

    #[test]
    fn ranks_are_permutation() {
        let tex = BlueNoiseTexture::embedded();
        let ranks = tex.as_slice();
        assert_eq!(ranks.len(), BlueNoiseTexture::PIXEL_COUNT);
        let mut seen = vec![false; BlueNoiseTexture::PIXEL_COUNT];
        for &r in ranks {
            assert!((r as usize) < BlueNoiseTexture::PIXEL_COUNT);
            assert!(!seen[r as usize], "duplicate rank {r}");
            seen[r as usize] = true;
        }
    }

    #[test]
    fn committed_raw_sha256_matches() {
        let bytes = include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../assets/blue_noise_128_u16.raw"
        ));
        let digest = format!("{:x}", Sha256::digest(bytes));
        let expected = include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../assets/blue_noise_128_u16.sha256"
        ))
        .split_whitespace()
        .next()
        .unwrap();
        assert_eq!(digest, expected);
    }

    #[test]
    fn rank_wraps_modulo_size() {
        let tex = BlueNoiseTexture::embedded();
        assert_eq!(tex.rank(0, 0), tex.rank(128, 128));
        assert_eq!(tex.rank(127, 0), tex.rank(255, 128));
    }
}
